6376, 'expenditures': 92642},\n    1964: {'receipts': 89459, 'expenditures': 97684},\n}\n\n# Exchange rates: USD per GBP (annual average)\n# To convert USD to GBP: GBP = USD / (USD per GBP)\n# For years where rate is X USD/GBP, divide USD by X to get GBP\n\nexchange_rates = {  # USD per GBP\n    1948: 4.03,\n    1949: 3.50,\n    1950: 2.80,\n    1951: 2.80,\n    1952: 2.80,\n    1953: 2.80,\n    1954: 2.80,\n    1955: 2.80,\n    1956: 2.80,\n    1957: 2.80,\n    1958: 2.80,\n    1959: 2.80,\n    1960: 2.80,\n    1961: 2.80,\n    1962: 2.80,\n    1963: 2.80,\n    1964: 2.80,\n}\n\n# Convert to GBP (in millions)\nreceipts_gbp = []\nexpenditures_gbp = []\n\nprint(\"Year | Rec USD | Rec GBP | Exp USD | Exp GBP\")\nprint(\"-\" * 60)\nfor year in sorted(fiscal_data.keys()):\n    rec_usd = fiscal_data[year]['receipts']\n    exp_usd = fiscal_data[year]['expenditures']\n    \n    rec_gbp = rec_usd / exchange_rates[year]\n    exp_gbp = exp_usd / exchange_rates[year]\n    \n    receipts_gbp.append(rec_gbp)\n    expenditures_gbp.append(exp_gbp)\n    \n    print(f\"{year} | {rec_usd} | {rec_gbp:.2f} | {exp_usd} | {exp_gbp:.2f}\")\n\n# Now calculate Pearson correlation coefficient\n# r = cov(X,Y) / (std(X) * std(Y))\n\nn = len(receipts_gbp)\nmean_rec = sum(receipts_gbp) / n\nmean_exp = sum(expenditures_gbp) / n\n\n# Calculate covariance\ncov = sum((receipts_gbp[i] - mean_rec) * (expenditures_gbp[i] - mean_exp) for i in range(n)) / (n - 1)\n\n# Calculate standard deviations\nvar_rec = sum((r - mean_rec)**2 for r in receipts_gbp) / (n - 1)\nvar_exp = sum((e - mean_exp)**2 for e in expenditures_gbp) / (n - 1)\nstd_rec = var_rec ** 0.5\nstd_exp = var_exp ** 0.5\n\n# Pearson correlation\nr = cov / (std_rec * std_exp)\n\nprint(f\"\\n=== Results ===\")\nprint(f\"Mean receipts (GBP millions): {mean_rec:.2f}\")\nprint(f\"Mean expenditures (GBP millions): {mean_exp:.2f}\")\nprint(f\"Covariance: {cov:.2f}\")\nprint(f\"Std receipts: {std_rec:.2f}\")\nprint(f\"Std expenditures: {std_exp:.2f}\")\nprint(f\"\\nPearson correlation coefficient: {r:.2f}\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
